-- HealthyApp — Supabase schema
-- Run this once in the Supabase dashboard: SQL Editor → New query → paste → Run

-- ── Plans ──────────────────────────────────────────────────────────────────
-- One active plan per user. The plan JSON (weeks/sessions/exercises/blocks)
-- is stored as-is in `data`, matching the format generated by Claude and
-- imported from the Settings screen.
create table if not exists plans (
  user_id uuid primary key references auth.users(id) on delete cascade,
  name text,
  description text,
  start_date date,
  data jsonb not null,
  updated_at timestamptz not null default now()
);

alter table plans enable row level security;

create policy "Users manage their own plan"
  on plans for all
  using (auth.uid() = user_id)
  with check (auth.uid() = user_id);

-- ── Completed sessions ───────────────────────────────────────────────────────
create table if not exists completed_sessions (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  session_id text not null,
  completed_at timestamptz not null default now(),
  unique (user_id, session_id)
);

alter table completed_sessions enable row level security;

create policy "Users manage their own completed sessions"
  on completed_sessions for all
  using (auth.uid() = user_id)
  with check (auth.uid() = user_id);

-- ── Session comments ─────────────────────────────────────────────────────────
create table if not exists session_comments (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  session_id text not null,
  text text not null,
  updated_at timestamptz not null default now(),
  unique (user_id, session_id)
);

alter table session_comments enable row level security;

create policy "Users manage their own session comments"
  on session_comments for all
  using (auth.uid() = user_id)
  with check (auth.uid() = user_id);

-- ── Weight entries ───────────────────────────────────────────────────────────
create table if not exists weight_entries (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users(id) on delete cascade,
  date date not null,
  weight numeric not null,
  type text not null check (type in ('official', 'control')),
  note text,
  created_at timestamptz not null default now()
);

alter table weight_entries enable row level security;

create policy "Users manage their own weight entries"
  on weight_entries for all
  using (auth.uid() = user_id)
  with check (auth.uid() = user_id);

-- ── Weight goal ──────────────────────────────────────────────────────────────
create table if not exists weight_goals (
  user_id uuid primary key references auth.users(id) on delete cascade,
  goal_weight numeric not null
);

alter table weight_goals enable row level security;

create policy "Users manage their own weight goal"
  on weight_goals for all
  using (auth.uid() = user_id)
  with check (auth.uid() = user_id);
